def solve(n, k):
    # Рыцарь => следующие k все лжецы, значит следующий рыцарь на расстоянии >= k+1.
    # Лжец => среди следующих k есть рыцарь, значит следующий рыцарь на расстоянии <= k+1.
    # Итог: рыцари строго через каждые k+1 мест, что возможно только если (k+1) | n.
    return n // (k + 1)
